INSERT INTO public.drills (id, name, category, duration, min_players, max_players, tactical, fixed, material, explanation, coaching_points, variants, sketch) VALUES
  ('wu-driehoek', 'Passen in driehoeken + loopscholing', 'warming-up', 10, 6, 25, false, false, 'pionnen, 1 bal per 3', 'Driehoeken met zijdes van 10 m. Pass en volg je bal. Na 5 min loopscholing in de breedte: knieheffen, hakken-billen, zijwaarts, versnellen.', ARRAY['Rustig opbouwen', 'Pass op de goede voet', 'Aannemen richting volgende pion']::text[], '{"10-13": "3–4 driehoeken", "14-19": "5–6 driehoeken", "20-25": "7–8 driehoeken, 2 rijen"}'::jsonb, '/oefeningen/wu-driehoek.svg'),
  ('wu-vierkant', 'Passen in het vierkant', 'warming-up', 10, 8, 25, false, false, '4 pionnen, 2 ballen per vierkant', 'Vierkant 12×12 m, rij bij elke pion. Pass naar rechts en sluit aan; na 2 min andere kant op, daarna twee ballen tegelijk.', ARRAY['Aanspeelbaar zijn met open houding', 'Pass hard en vlak', 'Communiceer']::text[], '{"10-13": "1 vierkant", "14-19": "2 vierkanten", "20-25": "3 vierkanten"}'::jsonb, '/oefeningen/wu-vierkant.svg'),
  ('wu-dynamisch', 'Dynamische warming-up in tweetallen', 'warming-up', 10, 4, 25, false, false, '1 bal per 2', 'Tweetallen op 10 m. Inspelen, kaatsen, loopoefening terug (zijwaarts, achteruit, sprintje). Afsluiten met korte rek van heupen en kuiten.', ARRAY['Tempo langzaam opvoeren', 'Twee voeten gebruiken']::text[], '{"10-13": "5–6 tweetallen", "14-19": "7–9 tweetallen", "20-25": "10–12 tweetallen in 2 rijen"}'::jsonb, '/oefeningen/wu-dynamisch.svg'),
  ('wu-rondo-licht', 'Lichte rondo 4 tegen 1', 'warming-up', 10, 5, 25, false, false, 'pionnen, 1 bal per groep', 'Vak 8×8 m, vier rondom, één in het midden. Na balverovering of na 1 minuut wisselen.', ARRAY['Rustig tempo', 'Kort en simpel spelen']::text[], '{"10-13": "2 groepen van 5–6", "14-19": "3 groepen", "20-25": "4–5 groepen"}'::jsonb, '/oefeningen/wu-rondo-licht.svg'),
  ('wu-tikkertje', 'Tikkertje met bal', 'warming-up', 8, 8, 25, false, false, 'hesjes, 1 bal per 2 tikkers', 'Vak 20×20 m. Twee tikkers die moeten tikken met de bal in de hand. Getikt = ook tikker. Laatste drie winnen.', ARRAY['Speels begin', 'Wendbaarheid']::text[], '{"10-13": "2 tikkers", "14-19": "3 tikkers", "20-25": "4 tikkers, vak 25×25 m"}'::jsonb, '/oefeningen/wu-tikkertje.svg'),
  ('wu-dribbel', 'Dribbelen in het vak', 'warming-up', 8, 4, 25, false, false, '1 bal per speler, pionnen', 'Iedereen dribbelt vrij in 20×20 m. Op signaal: richting veranderen, binnenkant/buitenkant, stoppen met zool, versnellen.', ARRAY['Kijk omhoog', 'Kleine aanrakingen']::text[], '{"10-13": "Vak 15×15 m", "14-19": "Vak 20×20 m", "20-25": "Vak 25×25 m"}'::jsonb, '/oefeningen/wu-dribbel.svg'),
  ('wu-overloop', 'Passen en overlappen', 'warming-up', 10, 6, 24, false, false, 'pionnen, 1 bal per rij', 'Twee rijen tegenover elkaar op 15 m. Pass, en loop om de rij heen naar de andere kant. Daarna éénmaal kaatsen via de middenspeler.', ARRAY['Na de pass direct bewegen', 'Tempo opvoeren']::text[], '{"10-13": "1 opstelling", "14-19": "2 opstellingen", "20-25": "3 opstellingen"}'::jsonb, '/oefeningen/wu-overloop.svg'),
  ('pas-rondo52', 'Rondo 5 tegen 2', 'passen', 15, 7, 25, false, false, 'pionnen, hesjes, 1 bal per vak', 'Vak 12×12 m, vijf rondom, twee in het midden. Wie balverlies lijdt gaat erin. 8 passes achter elkaar = punt.', ARRAY['Open houding, kijken vóór je de bal krijgt', 'Maximaal 2 balcontacten', 'Jagers samen druk zetten']::text[], '{"10-13": "2 vakken (5:2 en 4:2)", "14-19": "3 vakken van 6", "20-25": "4 vakken van 5–6"}'::jsonb, '/oefeningen/pas-rondo52.svg'),
  ('pas-positie444', 'Positiespel 4+4 tegen 4', 'passen', 15, 12, 24, false, false, 'hesjes in 3 kleuren, pionnen', 'Vak 25×25 m. Twee teams spelen samen tegen het derde. Wie de bal verliest wordt verdediger.', ARRAY['Breedte en diepte maken', 'Driehoeken vormen', 'Snel omschakelen na balverlies']::text[], '{"10-13": "3+3 tegen 3 (vak 20×20)", "14-19": "4+4 tegen 4 (+ jokers)", "20-25": "2 vakken naast elkaar"}'::jsonb, '/oefeningen/pas-positie444.svg'),
  ('pas-jokers', '4 tegen 4 met kaatsers', 'passen', 15, 10, 25, false, false, 'hesjes, pionnen', 'Vak 25×20 m. 4 tegen 4 in het vak, aan elke kopse kant een kaatser. Punt bij pass van kaatser naar kaatser.', ARRAY['Diep kijken', 'Aanbieden tussen de linies']::text[], '{"10-13": "3 tegen 3 + 2 kaatsers", "14-19": "4 tegen 4 + 2 kaatsers, wissel", "20-25": "2 velden"}'::jsonb, '/oefeningen/pas-jokers.svg'),
  ('pas-y', 'Passpatroon Y-vorm', 'passen', 12, 6, 20, false, false, '5 pionnen, 3 ballen', 'Y-opstelling. Pass – kaats – diepe bal – aannemen en doorspelen. Spelers schuiven op naar de volgende pion.', ARRAY['Timing van het aanbieden', 'Aanname richting doorspelen']::text[], '{"10-13": "1 Y", "14-19": "2 Y''s", "20-25": "3 Y''s, wedstrijdje snelste rondje"}'::jsonb, '/oefeningen/pas-y.svg'),
  ('pas-poortjes', 'Poortjesspel', 'passen', 12, 8, 24, false, false, '6–8 poortjes van pionnen', 'Twee teams in 30×30 m met poortjes. Pass door een poortje naar een medespeler = punt.', ARRAY['Vrijlopen', 'Kijk waar ruimte is']::text[], '{"10-13": "5 tegen 5, 6 poortjes", "14-19": "7 tegen 7 of 3 teams", "20-25": "2 velden"}'::jsonb, '/oefeningen/pas-poortjes.svg'),
  ('pas-3zones', 'Spel over drie zones', 'passen', 15, 12, 24, true, false, 'hesjes, pionnen', 'Veld in drie zones. Bal moet van zone 1 via zone 2 naar zone 3. Middenzone 2 tegen 1, buitenzones 4 tegen 2.', ARRAY['Lijnen overslaan als het kan', 'Middenvelder: draaien of kaatsen']::text[], '{"10-13": "3:1 in de buitenzones", "14-19": "4:2 in de buitenzones", "20-25": "Grotere zones, 5:2"}'::jsonb, '/oefeningen/pas-3zones.svg'),
  ('pas-lange-bal', 'Lange bal en aannemen', 'passen', 12, 4, 25, false, false, '1 bal per 2', 'Tweetallen op 25–30 m. Lange bal door de lucht, aannemen met borst/dij/voet in één beweging, terugspelen.', ARRAY['Standbeen naast de bal', 'Aanname weg van de denkbeeldige tegenstander']::text[], '{"10-13": "5–6 tweetallen", "14-19": "7–9 tweetallen", "20-25": "10–12 tweetallen"}'::jsonb, '/oefeningen/pas-lange-bal.svg'),
  ('af-kaats', 'Kaatsen en afwerken', 'afwerken', 15, 6, 25, false, false, 'doel, keeper, ballen', 'Twee rijen voor één doel, een kaatser bij de 16. Pass, kaats, schieten. Keepers wisselen om de 5 minuten.', ARRAY['Passen op tempo', 'Laag en hard afwerken', 'Naschieten']::text[], '{"10-13": "1 doel", "14-19": "2 doelen", "20-25": "2 doelen, 2 kaatsers per doel"}'::jsonb, '/oefeningen/af-kaats.svg'),
  ('af-voorzet', 'Voorzetten en koppen', 'afwerken', 15, 8, 20, false, false, 'doel, keeper, ballen', 'Vleugelspeler dribbelt op en geeft voorzet; twee spelers lopen in op eerste en tweede paal.', ARRAY['Looplijnen kruisen', 'Voorzet vóór de keeper weg']::text[], '{"10-13": "Één kant", "14-19": "Beide kanten om en om", "20-25": "Beide kanten + verdediger erbij"}'::jsonb, '/oefeningen/af-voorzet.svg'),
  ('af-1op1', '1 tegen 1 op het doel', 'afwerken', 12, 6, 25, false, false, 'doel, keeper, hesjes', 'Aanvaller en verdediger starten op 25 m. Trainer speelt in, 1 tegen 1 tot afronding.', ARRAY['Tempo maken', 'Verdediger: dwing naar buiten']::text[], '{"10-13": "1 doel", "14-19": "2 doelen", "20-25": "2 doelen, ook 2 tegen 1"}'::jsonb, '/oefeningen/af-1op1.svg'),
  ('af-2tegen1', '2 tegen 1 naar het doel', 'afwerken', 15, 6, 25, true, false, 'doel, keeper, hesjes', 'Twee aanvallers tegen één verdediger vanaf de middenlijn. Daarna direct terug als 1 tegen 2.', ARRAY['Verdediger uitlokken, dan afspelen', 'Breedte houden']::text[], '{"10-13": "1 doel", "14-19": "2 doelen", "20-25": "3 tegen 2"}'::jsonb, '/oefeningen/af-2tegen1.svg'),
  ('af-draaien', 'Aannemen, draaien en schieten', 'afwerken', 12, 4, 25, false, false, 'doel, keeper, pionnen', 'Speler staat met de rug naar het doel, krijgt de bal, draait weg langs de pion en schiet.', ARRAY['Over de schouder kijken', 'Aanname in de draairichting']::text[], '{"10-13": "1 doel", "14-19": "2 doelen", "20-25": "2 doelen + passieve verdediger"}'::jsonb, '/oefeningen/af-draaien.svg'),
  ('af-3tegen2', '3 tegen 2 met terugkeer', 'afwerken', 15, 10, 25, true, false, '2 doelen, keepers, hesjes', 'Drie aanvallers tegen twee verdedigers. Na de actie gaan de twee verdedigers plus één nieuwe speler de andere kant op.', ARRAY['Snel uitspelen', 'Diepte en breedte', 'Omschakelen']::text[], '{"10-13": "2 tegen 1", "14-19": "3 tegen 2", "20-25": "3 tegen 2, 2 velden"}'::jsonb, '/oefeningen/af-3tegen2.svg'),
  ('af-afstand', 'Schieten van afstand', 'afwerken', 10, 4, 25, false, false, 'doel, keeper, ballen', 'Afspeler legt de bal klaar op 18–22 m, speler schiet in één keer.', ARRAY['Over de bal heen', 'Wreef, enkel strak']::text[], '{"10-13": "1 doel", "14-19": "2 doelen", "20-25": "2 doelen + wedstrijdje tussen teams"}'::jsonb, '/oefeningen/af-afstand.svg'),
  ('tac-opbouw', 'Opbouwen van achteruit', 'tactisch', 15, 10, 24, true, false, 'doel, keeper, 2 kleine doeltjes', 'Keeper + 3 verdedigers + 1 middenvelder tegen 3 aanvallers. Opbouwers scoren door de middenlijn te passeren of in kleine doeltjes.', ARRAY['Keeper doet mee', 'Breed maken', 'Rustig blijven onder druk']::text[], '{"10-13": "K+3 tegen 2", "14-19": "K+4 tegen 3", "20-25": "Twee groepen wisselen elke 5 min"}'::jsonb, '/oefeningen/tac-opbouw.svg'),
  ('tac-druk', 'Samen druk zetten', 'tactisch', 15, 12, 24, true, false, 'hesjes, kleine doeltjes', '6 tegen 6 op half veld. Verdedigende ploeg mag pas druk zetten als de bal naar een backlijn gaat; na balverovering scoren binnen 6 seconden.', ARRAY['Signaal herkennen', 'Compact blijven', 'Kort op elkaar']::text[], '{"10-13": "4 tegen 4", "14-19": "6 tegen 6", "20-25": "7 tegen 7 + wissels"}'::jsonb, '/oefeningen/tac-druk.svg'),
  ('tac-omschakelen', 'Omschakelen 4 tegen 4 + 2', 'tactisch', 15, 10, 24, true, false, '2 doelen, keepers', '4 tegen 4 met 2 jokers voor het team in balbezit. Na balverovering direct de diepte zoeken.', ARRAY['Eerste pass vooruit', 'Na balverlies direct druk']::text[], '{"10-13": "3 tegen 3 + 2", "14-19": "4 tegen 4 + 2", "20-25": "5 tegen 5 + 2"}'::jsonb, '/oefeningen/tac-omschakelen.svg'),
  ('tac-verdedigen', 'Verdedigen in linie', 'tactisch', 15, 8, 20, true, false, 'doel, keeper, hesjes', 'Achterlinie van 3 tegen 4 aanvallers die de bal rondspelen. Linie schuift mee met de bal, trainer stopt en corrigeert.', ARRAY['Schuiven naar de balkant', 'Coachen van achteruit', 'Niet te diep zakken']::text[], '{"10-13": "3 verdedigers tegen 3", "14-19": "3 tegen 4", "20-25": "4 tegen 5, twee groepen"}'::jsonb, '/oefeningen/tac-verdedigen.svg'),
  ('tac-vleugel', 'Spel over de vleugel', 'tactisch', 15, 12, 24, true, false, 'doel, keeper, pionnen', 'Partij met aan beide kanten een vrije vleugelzone. Doelpunt na voorzet uit de zone telt dubbel.', ARRAY['Overlappen', 'Op tijd in de 16']::text[], '{"10-13": "4 tegen 4", "14-19": "6 tegen 6", "20-25": "7 tegen 7"}'::jsonb, '/oefeningen/tac-vleugel.svg'),
  ('tac-overtal', 'Overtal uitspelen 3 tegen 2', 'tactisch', 12, 10, 24, true, false, '2 doelen, keepers', 'Uit een rij drie aanvallers tegen twee verdedigers. Daarna 2 tegen 1 de andere kant op.', ARRAY['Speler met bal dwingt keuze af', 'Goede timing van de pass']::text[], '{"10-13": "2 tegen 1", "14-19": "3 tegen 2", "20-25": "3 tegen 2, 2 velden"}'::jsonb, '/oefeningen/tac-overtal.svg'),
  ('tac-standaard', 'Hoekschoppen en vrije trappen', 'tactisch', 10, 10, 24, true, false, 'doel, keeper, ballen', 'Per team de eigen afspraken voor hoekschoppen en vrije trappen oefenen, aanvallend en verdedigend.', ARRAY['Vaste looplijnen', 'Zone of mandekking afspreken']::text[], '{"10-13": "5 tegen 5", "14-19": "7 tegen 7", "20-25": "Beide teams om de beurt"}'::jsonb, '/oefeningen/tac-standaard.svg'),
  ('pv-77', 'Partij op half veld', 'partijvorm', 25, 10, 25, true, false, '2 doelen, hesjes', 'Wedstrijdvorm zoals in de competitie, op grote doelen. Geen wissels.', ARRAY['Speelwijze van het eigen team', 'Communicatie']::text[], '{"10-13": "2 teams: 5 tegen 5 of 6 tegen 6", "14-19": "Tot en met 15 spelers: 2 teams van 7. Vanaf 16: 4 teams op 2 velden", "20-25": "4 teams op 2 velden: 5 tegen 5 of 6 tegen 6"}'::jsonb, '/oefeningen/pv-77.svg'),
  ('pv-4doeltjes', 'Partij op 4 kleine doeltjes', 'partijvorm', 20, 10, 25, false, false, '4 kleine doeltjes, hesjes', 'Elk team verdedigt twee doeltjes en valt er twee aan. Geen keepers.', ARRAY['Van kant wisselen', 'Overzicht houden']::text[], '{"10-13": "2 teams: 5 tegen 5 of 6 tegen 6", "14-19": "Tot en met 15 spelers: 2 teams van 7. Vanaf 16: 4 teams op 2 velden (8 doeltjes)", "20-25": "4 teams op 2 velden: 5 tegen 5 of 6 tegen 6 (8 doeltjes)"}'::jsonb, '/oefeningen/pv-4doeltjes.svg'),
  ('pv-2raak', 'Partij met twee keer raken', 'partijvorm', 20, 10, 25, false, false, '2 doelen, hesjes', 'Partij waarin elke speler maximaal 2 keer de bal mag raken. Na 10 minuten vrij spel.', ARRAY['Vooraf kijken', 'Veel vrijlopen']::text[], '{"10-13": "2 teams: 5 tegen 5 of 6 tegen 6", "14-19": "Tot en met 15 spelers: 2 teams van 7. Vanaf 16: 4 teams op 2 velden", "20-25": "4 teams op 2 velden: 5 tegen 5 of 6 tegen 6"}'::jsonb, '/oefeningen/pv-2raak.svg'),
  ('pv-lijnvoetbal', 'Lijnvoetbal', 'partijvorm', 20, 8, 25, false, false, 'pionnen, hesjes', 'Scoren door met de bal aan de voet over de achterlijn te dribbelen.', ARRAY['Diepte zoeken', 'Dribbel in de ruimte']::text[], '{"10-13": "2 teams: 5 tegen 5 of 6 tegen 6", "14-19": "Tot en met 15 spelers: 2 teams van 7. Vanaf 16: 4 teams op 2 velden", "20-25": "4 teams op 2 velden: 5 tegen 5 of 6 tegen 6"}'::jsonb, '/oefeningen/pv-lijnvoetbal.svg'),
  ('pv-team-tegen-team', 'Team 1 tegen Team 2', 'partijvorm', 25, 14, 25, true, false, '2 doelen, hesjes', 'Beide eigen teams tegen elkaar als oefenwedstrijd, met de opstelling die je in de competitie speelt.', ARRAY['Eigen afspraken toepassen']::text[], '{"10-13": "Gemengd: 5 tegen 5 of 6 tegen 6", "14-19": "Tot en met 15 spelers: Team 1 tegen Team 2. Vanaf 16: elk team in tweeën, op 2 velden", "20-25": "Elk team in tweeën, Team 1 tegen Team 2 op 2 velden"}'::jsonb, '/oefeningen/pv-team-tegen-team.svg'),
  ('vast-rondje-max', 'Rondje van Max', 'conditie', 10, 1, 25, false, true, '4 pionnen', 'Vierkant van 16×16 m. Twee zijdes rustig lopen, één zijde snel, doorlopen tot 10 versnellingen.', ARRAY['Echt versnellen op de snelle zijde', 'Rustig herstellen']::text[], '{"10-13": "1 vierkant", "14-19": "1 vierkant, start op 2 hoeken", "20-25": "2 vierkanten"}'::jsonb, '/oefeningen/vast-rondje-max.svg')
