-- Training-module 3/3: de 34 oefeningen uit de bibliotheek.
-- Opnieuw draaien werkt de teksten bij en laat zelf toegevoegde oefeningen staan.
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, category = EXCLUDED.category, duration = EXCLUDED.duration,
  min_players = EXCLUDED.min_players, max_players = EXCLUDED.max_players,
  tactical = EXCLUDED.tactical, fixed = EXCLUDED.fixed, material = EXCLUDED.material,
  explanation = EXCLUDED.explanation, coaching_points = EXCLUDED.coaching_points,
  variants = EXCLUDED.variants, sketch = EXCLUDED.sketch;
